<script setup>
import BusynessMeter from '../components/BusynessMeter.vue';
import BrandLogo from '../components/BrandLogo.vue';
import ArrowIcon from '../components/ArrowIcon.vue';
import { ref,reactive,computed,watch,onMounted,onUnmounted } from 'vue';
import {services} from '../lib/barber';
import {t,language,toggleLanguage,today,api,useTeam,notifyTeamUpdated} from '../lib/state';
const {team,error:teamError,refresh}=useTeam();
const session=ref(null),authorized=ref(null),error=ref(''),message=ref(''),busy=ref(false),view=ref('charts'),date=ref(today()),barber=ref('all'),rows=ref([]),dashboard=ref(null);
const accountType=ref('manager'),loginBarber=ref('marco'),pin=ref('');
const newPerson=reactive({name:'',accessCode:'',serviceIds:[]});const drafts=reactive({});
const passwords=reactive({});
const pending=ref(null),dialog=ref(null);
const sections=[{id:'charts',label:'Gráficas'},{id:'clients',label:'Clientes'},{id:'team',label:'Team & services'},{id:'schedule',label:'Agenda'}];
const money=value=>new Intl.NumberFormat(language.value==='es'?'es-US':'en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(value);
const barberName=id=>team.value?.find(p=>p.id===id)?.name||id;
const serviceName=id=>t(services.find(s=>s.id===id)?.name||id);
const confirmed=computed(()=>rows.value.filter(r=>r.status==='confirmed').length);
const completed=computed(()=>rows.value.filter(r=>r.status==='completed').length);
const chartMax=computed(()=>Math.max(1,...(dashboard.value?.week||[]).flatMap(d=>[d.reserved,d.completed,d.cancelled])));
const demandMax=computed(()=>Math.max(1,...(dashboard.value?.serviceDemand||[]).map(d=>d.count)));
watch(team,people=>{for(const p of people||[])if(!drafts[p.id])drafts[p.id]=[...p.serviceIds];});
const dirty=person=>[...(drafts[person.id]||[])].sort().join()!==[...person.serviceIds].sort().join();
let scheduleSequence=0,stopped=false,interval;
async function load(){const seq=++scheduleSequence;try{const data=await api(`/api/appointments?date=${date.value}${barber.value==='all'?'':'&barber='+barber.value}`);if(stopped||seq!==scheduleSequence)return;rows.value=data.appointments;session.value=data.session;authorized.value=true;error.value='';}catch(e){if(stopped||seq!==scheduleSequence)return;if(e.status===401){authorized.value=false;session.value=null;rows.value=[];dashboard.value=null;}else error.value=e.message;}}
async function overview(){if(session.value?.role!=='manager')return;try{dashboard.value=await api('/api/staff/dashboard');}catch(e){error.value=e.message;}}
async function login(){busy.value=true;error.value='';try{await api('/api/staff/login',{pin:pin.value,...(accountType.value==='barber'?{barberId:loginBarber.value}:{})});pin.value='';view.value='charts';await load();await overview();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function logout(){busy.value=true;try{await api('/api/staff/logout',{});session.value=null;authorized.value=false;rows.value=[];dashboard.value=null;}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function update(id,status){busy.value=true;error.value='';try{await api('/api/staff/status',{id,status});await load();await overview();}catch(e){error.value=e.message;}finally{busy.value=false;}}
function requestUpdate(row,event){const status=event.target.value;event.target.value=row.status;if(session.value?.role==='barber'){pending.value={row,status};dialog.value.showModal();}else update(row.id,status);}
function dismiss(){dialog.value.close();pending.value=null;}
function confirm(){const change=pending.value;dismiss();if(change)update(change.row.id,change.status);}
async function save(person){busy.value=true;message.value='';error.value='';try{await api('/api/staff/services',{staffId:person.id,serviceIds:drafts[person.id]});await refresh();notifyTeamUpdated();message.value='Services saved. New reservations now use these permissions.';}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function changePassword(person){busy.value=true;message.value='';error.value='';try{await api('/api/staff/password',{staffId:person.id,accessCode:passwords[person.id]});passwords[person.id]='';message.value='Password updated. Use the new password to sign in.';}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function add(){busy.value=true;message.value='';error.value='';try{await api('/api/staff/team',{...newPerson});newPerson.name='';newPerson.accessCode='';newPerson.serviceIds=[];await refresh();notifyTeamUpdated();message.value='Professional added. Their profile is now available for authorized services and staff sign-in.';}catch(e){error.value=e.message;}finally{busy.value=false;}}
watch([date,barber],()=>{if(authorized.value)load();});
watch(view,()=>{if(['charts','clients'].includes(view.value))overview();});
watch(session,(value,old)=>{if(value?.role==='manager'&&old?.role!=='manager')overview();});
onMounted(()=>{load();interval=setInterval(()=>{if(authorized.value){load();if(['charts','clients'].includes(view.value))overview();}},30000);});
onUnmounted(()=>{stopped=true;clearInterval(interval);});
</script>
<template>
<main class="staff-page"><dialog ref="dialog" class="staff-confirmation" aria-labelledby="confirmation-title" @cancel.prevent="dismiss"><h2 id="confirmation-title">{{t('Confirm appointment change')}}</h2><p>{{t('You are about to mark this appointment as')}} <strong>{{t(pending?.status==='completed'?'Completed':'Cancelled')}}</strong>.</p><p>{{pending?.row.customerName}} · {{pending?.row.time}}</p><div><button @click="dismiss">{{t('Keep current status')}}</button><button @click="confirm">{{t('Confirm change')}}</button></div></dialog>
<header class="staff-header"><a class="brand" href="/"><BrandLogo /></a><button class="language-toggle" @click="toggleLanguage">{{language==='en'?'ES':'EN'}}</button><a href="/"><ArrowIcon direction="left" /> {{t('← BACK TO SITE').replace('← ', '')}}</a></header>
<div class="staff-container"><p class="eyebrow">Steve's Barbershop · {{t(session?.role==='manager'?'MANAGEMENT':session?.role==='barber'?'BARBER DESK':'STAFF')}}</p><h1 v-if="session?.role==='manager'">{{t('MANAGER')}} <em>{{t('DESK.')}}</em></h1><h1 v-else-if="session">{{t('YOUR')}} <em>{{t('CHAIR.')}}</em></h1><h1 v-else>{{t('THE')}} <em>{{t('APPOINTMENTS.')}}</em></h1>
<p v-if="authorized===null" class="staff-loading" role="status">{{t('Loading schedule…')}}</p>
<div v-else-if="!session" class="login-card"><p class="eyebrow">{{t('PRIVATE ACCESS')}}</p><h2>{{t('Welcome back.')}}</h2><p>{{t('Sign in to manage Steve\'s Barbershop schedule.')}}</p><form @submit.prevent="login"><label>{{t('Access level')}}<select v-model="accountType"><option value="manager">{{t('Manager')}}</option><option value="barber">{{t('Barber')}}</option></select></label><label v-if="accountType==='barber'">{{t('Your profile')}}<select v-model="loginBarber"><option v-for="person in team||[]" :key="person.id" :value="person.id">{{person.name}}</option></select></label><label>{{t('Access code')}}<input v-model="pin" type="password" required autocomplete="current-password"></label><button class="submit-button" :disabled="busy">{{busy?t('SIGNING IN'):t('OPEN YOUR DESK')}}<span aria-hidden="true"><ArrowIcon /></span></button></form></div>
<template v-else><BusynessMeter editable /><div class="staff-welcome"><div><span>{{t(session.role==='manager'?'MANAGER VIEW':'PERSONAL SCHEDULE')}}</span><strong>{{session.role==='manager'?t('All barbers, one clear view.'):barberName(session.barberId)}}</strong></div><button :disabled="busy" @click="logout">{{t('Sign out')}} <span aria-hidden="true"><ArrowIcon /></span></button></div>
<div v-if="session.role==='manager'" class="manager-navigation"><span>{{t(sections.find(s=>s.id===view)?.label)}}</span><details class="manager-section-menu" @keydown.esc="e=>{e.currentTarget.open=false}"><summary>{{t('Secciones')}} <span aria-hidden="true">⌄</span></summary><nav aria-label="Secciones del manager"><button v-for="item in sections" :key="item.id" :aria-current="view===item.id?'page':undefined" @click="e=>{view=item.id;e.currentTarget.closest('details').open=false}"><strong>{{t(item.label)}}</strong></button></nav></details></div>
<template v-if="session.role==='manager'&&view==='charts'"><p v-if="!dashboard" role="status">{{t('Loading schedule…')}}</p><template v-else><section class="manager-panel"><p class="eyebrow">{{t('CURRENT WEEK · USD')}}</p><h2>{{t('Planned revenue')}}</h2><p>{{dashboard.week[0].date}} — {{dashboard.week[6].date}}</p><p class="manager-note">{{t('Reserved: pending confirmed appointments. Completed: services already provided. Amounts use current service prices.')}}</p><div class="vue-chart" role="img" :aria-label="t('Daily reserved, completed and canceled revenue. Values are also available in the table below.')"><div v-for="day in dashboard.week" :key="day.date" class="vue-chart-day"><div class="vue-bars"><span v-for="kind in ['reserved','completed','cancelled']" :key="kind" :class="kind" :style="{height:(day[kind]/chartMax*160)+'px'}" :title="day.date+' '+t(kind)+' '+money(day[kind])"></span></div><small>{{day.date.slice(5)}}</small></div></div><div class="chart-legend"><span>● {{t('Reserved')}}</span><span>● {{t('Completed')}}</span><span>● {{t('Cancelled')}}</span></div><details><summary>{{t('View daily amounts')}}</summary><div class="manager-table-scroll"><table><thead><tr><th>{{t('Date')}}</th><th>{{t('Reserved')}}</th><th>{{t('Completed')}}</th><th>{{t('Cancelled')}}</th></tr></thead><tbody><tr v-for="day in dashboard.week" :key="day.date"><td>{{day.date}}</td><td>{{money(day.reserved)}}</td><td>{{money(day.completed)}}</td><td>{{money(day.cancelled)}}</td></tr></tbody></table></div></details></section><section class="manager-panel"><p class="eyebrow">{{t('CLIENT PREFERENCES')}}</p><h2>{{t('Most requested services')}}</h2><p>{{dashboard.totalRequests}} {{t('bookings')}}</p><p class="manager-note">{{t('All history · Includes confirmed and completed bookings. Excludes cancellations.')}}</p><div v-for="s in dashboard.serviceDemand" :key="s.id" class="vue-demand"><strong>{{t(s.name)}}</strong><div><span :style="{width:s.count/demandMax*100+'%'}"></span></div><small>{{s.count}} · {{t('Reserved')}} {{s.reserved}} / {{t('Completed')}} {{s.completed}}</small></div></section></template></template>
<section v-if="session.role==='manager'&&view==='clients'" class="manager-panel"><p class="eyebrow">{{t('CLIENTS')}}</p><h2>{{t('Client history')}}</h2><p v-if="!dashboard" role="status">{{t('Loading schedule…')}}</p><p v-else-if="!dashboard.clients.length">{{t('No clients yet.')}}</p><article v-for="client in dashboard?.clients||[]" :key="client.email" class="vue-client"><h3>{{client.name}}</h3><p><a :href="'mailto:'+client.email">{{client.email}}</a> · <a :href="'tel:'+client.phone">{{client.phone}}</a></p><p>{{t('Last visit')}}: {{client.visits[0]?.date||t('No completed visits')}} · {{t('Next booking')}}: {{client.upcoming[0]?.date||t('No upcoming booking')}}</p><details><summary>{{t('View visits')}}</summary><p v-for="row in [...client.upcoming,...client.visits]" :key="row.id">{{row.date}} · {{row.time}} · {{serviceName(row.serviceId)}} · {{barberName(row.barberId)}} · {{t(row.status==='completed'?'Completed':'Confirmed')}}</p></details></article></section>
<section v-if="session.role==='manager'&&view==='team'" class="manager-panel team-services"><p class="eyebrow">{{t('TEAM & ACTIVITIES')}}</p><h2>{{t('Who can perform each service')}}</h2><p class="manager-note">{{t('Select the services each barber can perform from the full menu.')}}</p><p class="manager-note">{{t('Clients can book only the activities enabled here. Existing appointments remain on the agenda; changes apply to new bookings.')}}</p><details class="add-professional"><summary>{{t('+ Add professional')}}</summary><form @submit.prevent="add"><fieldset :disabled="busy"><legend>{{t('New professional')}}</legend><div class="new-person-fields"><label>{{t('Full name')}}<input v-model="newPerson.name" required minlength="2" maxlength="80" autocomplete="off"></label><label>{{t('Personal access code')}}<input v-model="newPerson.accessCode" type="password" required minlength="8" maxlength="64" autocomplete="new-password"><small>{{t('8–64 characters. The code is saved securely and is not shown again.')}}</small></label></div><div class="new-person-services"><label v-for="s in services" :key="s.id" class="team-service"><input v-model="newPerson.serviceIds" type="checkbox" :value="s.id"><span>{{t(s.name)}}</span></label></div><p v-if="!newPerson.serviceIds.length" class="manager-note">{{t('No services enabled: this professional will not receive new reservations.')}}</p><button class="submit-button">{{busy?t('Adding professional…'):t('Create professional')}}</button></fieldset></form></details><div class="team-cards"><fieldset v-for="person in team||[]" :key="person.id" class="team-card" :disabled="busy"><legend>{{person.name}}</legend><p class="field-label">{{t('Authorized services')}}</p><label v-for="s in services" :key="s.id" class="team-service"><input v-model="drafts[person.id]" type="checkbox" :value="s.id"><span>{{t(s.name)}}</span></label><p v-if="!drafts[person.id]?.length" class="manager-note">{{t('No services enabled: this professional will not receive new reservations.')}}</p><button class="submit-button" :disabled="busy||!dirty(person)" @click="save(person)">{{busy?t('Saving…'):t('Save services')}}</button><small class="team-save-state">{{t(dirty(person)?'Unsaved changes':'Saved configuration')}}</small><form class="team-password" @submit.prevent="changePassword(person)"><label>{{t('New password')}}<input v-model="passwords[person.id]" type="password" minlength="8" maxlength="64" required autocomplete="new-password" :aria-label="t('New password')+' · '+person.name"></label><button class="submit-button" :disabled="busy||!passwords[person.id]||passwords[person.id].length<8">{{t('Change password')}}</button></form></fieldset></div></section>
<template v-if="session.role==='barber'||view==='schedule'"><div class="staff-metrics"><article><span>{{t('APPOINTMENTS')}}</span><strong>{{rows.length}}</strong><small>{{t('Selected day')}}</small></article><article><span>{{t('CONFIRMED')}}</span><strong>{{confirmed}}</strong><small>{{t('Ready for the chair')}}</small></article><article><span>{{t('COMPLETED')}}</span><strong>{{completed}}</strong><small>{{language==='es'?'Valor reservado':'Booked value'}} {{money(rows.reduce((sum,row)=>sum+(row.status==='cancelled'?0:(services.find(s=>s.id===row.serviceId)?.price||0)),0))}}</small></article></div><div class="staff-toolbar"><label>{{t('Date')}}<input v-model="date" type="date"></label><label v-if="session.role==='manager'">{{t('Barber')}}<select v-model="barber"><option value="all">{{t('All barbers')}}</option><option v-for="person in team||[]" :key="person.id" :value="person.id">{{person.name}}</option></select></label><button @click="load">{{t('Refresh schedule')}}</button></div><p class="schedule-count">{{rows.length}} · {{date}}</p><div v-if="rows.length" class="appointment-list"><article v-for="row in rows" :key="row.id" class="appointment"><div class="appointment-time">{{row.time}}<small>{{t(row.status==='confirmed'?'Confirmed':row.status==='completed'?'Completed':'Cancelled')}}</small></div><div class="appointment-main"><h2>{{row.customerName}}</h2><p>{{serviceName(row.serviceId)}} · {{barberName(row.barberId)}}</p><p><a :href="'tel:'+row.customerPhone">{{row.customerPhone}}</a> · <a :href="'mailto:'+row.customerEmail">{{row.customerEmail}}</a></p><p v-if="row.notes" class="appointment-notes">“{{row.notes}}”</p></div><div class="appointment-actions"><select v-if="row.status==='confirmed'" :value="row.status" :disabled="busy" :aria-label="t('Status for')+' '+row.customerName" @change="requestUpdate(row,$event)"><option value="confirmed">{{t('Confirmed')}}</option><option value="completed">{{t('Completed')}}</option><option value="cancelled">{{t('Cancelled')}}</option></select><span v-else>{{t(row.status==='completed'?'Completed':'Cancelled')}}</span></div></article></div><div v-else class="empty-schedule"><span>{{t('NO APPOINTMENTS')}}</span><p>{{t('Your schedule is clear for this date.')}}</p></div></template>
</template><p v-if="error||teamError" class="form-error" role="alert">{{t(error||teamError)}}</p><p v-if="message" class="team-success" role="status">{{t(message)}}</p></div></main>
</template>
